"""Generated by socket-patch. Do not edit.

Re-declares the hub spoke of a patched package so that it is built from the wheel committed
under .socket/vendor/. A pin applies only while the hub still pins the recorded version of the
package; after a version bump the hub's own definition is left alone.
"""

load("@rules_python//python/pip_install:pip_repository.bzl", "whl_library")

_PINS = {
    "pypi_spvictim": struct(
        package = "spvictim",
        version = "1.0.0",
        urls = ["https://socket-patch.invalid/vendored/pypi/0b5e1c1e-0000-4000-8000-0000000000a1/spvictim-1.0.0-py3-none-any.whl"],
        sha256 = "163091302c981212db61955da517d58932b876d41c8db59fa0f1e1843a490f5f",
        filename = "spvictim-1.0.0-py3-none-any.whl",
    ),
}

# What native.existing_rule() returns beside the repository rule's own attributes.
_NOT_ATTRS = [
    "name",
    "kind",
    "generator_name",
    "generator_function",
    "generator_location",
    "visibility",
    "transitive_configs",
    "tags",
    "features",
    "compatible_with",
    "restricted_to",
    "aspect_hints",
    "expect_failure",
]

# The spoke of a pip-fetched requirement: `whl_library` up to rules_python 2.3.x, `pip_archive` from 2.4.0.
_KINDS = ["whl_library", "pip_archive"]

def _pinned(requirement):
    """(normalized name, version) of a `name[extras]==version ...` requirement line, else None."""
    head = requirement.split(" ")[0].split(";")[0]
    name, sep, version = head.partition("==")
    if not sep:
        return None
    name = name.split("[")[0].lower().replace("_", "-").replace(".", "-")
    return (name, version)

def _pin_kwargs(pin):
    out = {}
    for key in ["urls", "sha256", "filename", "whl_file"]:
        if hasattr(pin, key):
            out[key] = getattr(pin, key)
    return out

def socket_patch_pypi():
    for name, pin in _PINS.items():
        rule = native.existing_rule(name)
        if not rule or rule.get("kind") not in _KINDS:
            continue
        if _pinned(rule.get("requirement", "")) != (pin.package, pin.version):
            # The hub no longer pins this version (the user bumped it): leave the hub's spoke alone.
            continue
        kwargs = {}
        for key, value in rule.items():
            if key in _NOT_ATTRS or value == None:
                continue
            kwargs[key] = list(value) if type(value) == "tuple" else value
        kwargs.update(_pin_kwargs(pin))
        whl_library(name = name, **kwargs)
